import{Z as e,e as s,f as t,a0 as r}from"./chunks/framework.DmpHOl9T.js";const h=JSON.parse('{"title":"Form Groups","description":"","frontmatter":{},"headers":[],"relativePath":"forms/form-groups.md","filePath":"forms/form-groups.md","lastUpdated":1782532814000}'),n={name:"forms/form-groups.md"};function a(i,o,l,g,u,p){return s(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="form-groups" tabindex="-1">Form Groups <a class="header-anchor" href="#form-groups" aria-label="Permalink to &quot;Form Groups&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For defaults, restrictions, and scale patterns, see <a href="/guides/control-panel-admin/form-groups-and-defaults-at-scale">Form groups and defaults at scale</a>.</p></div><p>Form groups help you organise forms in the control panel. They are useful when you manage many forms and want sidebar filters, clearer navigation, and a consistent place to create new forms.</p><p>Form groups are <strong>control panel organisation</strong> with an optional <strong>policies layer</strong> for defaults and restrictions. They do not change how a form renders on the front end, which template an existing form uses, or how existing submissions behave until you change form settings.</p><h2 id="group-settings" tabindex="-1">Group Settings <a class="header-anchor" href="#group-settings" aria-label="Permalink to &quot;Group Settings&quot;">​</a></h2><p>When editing a form group under <strong>Formie → Settings → Form Groups</strong>, you can configure optional group settings across several tabs:</p><ul><li><strong>General</strong> — name, handle, and allowed submission statuses</li><li><strong>Field Palette</strong> — optional custom palette (toggle on tab; inherits global when off)</li><li><strong>Form Defaults</strong>, <strong>Field Defaults</strong>, <strong>Validation Messages</strong>, <strong>Notification Defaults</strong>, <strong>Integration Defaults</strong> — same panels as global <strong>Settings → Defaults</strong>, with blank values inheriting from global settings</li></ul><p>Blank group settings inherit from global <strong>Formie → Settings</strong> defaults.</p><h3 id="site-policy-multi-site" tabindex="-1">Site Policy (Multi-Site) <a class="header-anchor" href="#site-policy-multi-site" aria-label="Permalink to &quot;Site Policy (Multi-Site)&quot;">​</a></h3><p>On multi-site Craft installs, each group can restrict <strong>which sites</strong> forms in the group exist on, and how new forms <strong>propagate</strong> across those sites. Configure this under the <strong>General</strong> tab → <strong>Site Policy</strong> (<strong>Enabled Sites</strong> and <strong>Site Propagation</strong>).</p><p>See <a href="/forms/multi-site-and-translation">Multi-Site &amp; Translation</a> for how availability differs from content translation, propagation modes, and form builder behaviour.</p><h3 id="allowed-submission-statuses" tabindex="-1">Allowed Submission Statuses <a class="header-anchor" href="#allowed-submission-statuses" aria-label="Permalink to &quot;Allowed Submission Statuses&quot;">​</a></h3><p>Use the <strong>Allowed Submission Statuses</strong> control in <strong>General</strong> to restrict which statuses are available for forms in the group. Choose <strong>All</strong> to allow every status. This policy applies to all forms in the group; individual forms cannot override it.</p><h3 id="custom-field-palette" tabindex="-1">Custom Field Palette <a class="header-anchor" href="#custom-field-palette" aria-label="Permalink to &quot;Custom Field Palette&quot;">​</a></h3><p>Open the <strong>Field Palette</strong> tab and enable <strong>Use custom field palette</strong>. Forms in this group use that palette instead of the global one. When disabled, the group inherits the global palette from <strong>Settings → Fields</strong>.</p><h3 id="submission-limits" tabindex="-1">Submission Limits <a class="header-anchor" href="#submission-limits" aria-label="Permalink to &quot;Submission Limits&quot;">​</a></h3><p><a href="/forms/submission-limits">Submission limits</a> are configured <strong>per form</strong>, not at the group level. A form group does not enforce a shared entry cap across all of its forms.</p><p>If your group often uses per-user or per-IP limits, preset <strong>Collect User</strong> or <strong>Collect IP</strong> on the group <strong>Form Defaults</strong> tab so new forms inherit the privacy settings those limits rely on.</p><p>Global abuse throttling lives under <strong>Settings → Spam Protection</strong> and applies site-wide — it is separate from form submission limits.</p><h2 id="when-to-use-form-groups" tabindex="-1">When to Use Form Groups <a class="header-anchor" href="#when-to-use-form-groups" aria-label="Permalink to &quot;When to Use Form Groups&quot;">​</a></h2><p>Form groups are especially helpful when:</p><ul><li>several teams each own a set of forms</li><li>you want sidebar filters instead of one long forms list</li><li>you create new forms into a known bucket by default</li></ul><p>If you only have a handful of forms, you can skip groups entirely. The forms index works fine with just <strong>All forms</strong>.</p><h2 id="managing-groups" tabindex="-1">Managing Groups <a class="header-anchor" href="#managing-groups" aria-label="Permalink to &quot;Managing Groups&quot;">​</a></h2><p>Create and manage groups under <strong>Formie → Settings → Form Groups</strong>.</p><p>Each group has:</p><ul><li>a name</li><li>a handle</li><li>a sort order</li></ul><p>Groups are stored in <a href="/get-started/configuration">project config</a>, so they can travel with the project across environments like statuses and stencils. Form group UIDs are used in the forms index source keys (<code>group:{uid}</code>), so sidebar filters stay stable after a database sync.</p><h2 id="forms-index" tabindex="-1">Forms Index <a class="header-anchor" href="#forms-index" aria-label="Permalink to &quot;Forms Index&quot;">​</a></h2><p>When at least one group exists, the forms index sidebar shows:</p><ul><li><strong>All forms</strong></li><li>a <strong>Groups</strong> heading with one source per group</li><li><strong>Ungrouped</strong> for forms with no group assigned</li></ul><p>When no groups exist, only <strong>All forms</strong> is shown.</p><h3 id="creating-a-new-form" tabindex="-1">Creating a New Form <a class="header-anchor" href="#creating-a-new-form" aria-label="Permalink to &quot;Creating a New Form&quot;">​</a></h3><p>On <strong>All forms</strong> or <strong>Ungrouped</strong>, the <strong>New Form</strong> button works like Craft’s entries and categories indexes: you can pick which group the new form should belong to from the split-button menu.</p><p>When you are already viewing a specific group, the primary <strong>New Form</strong> action creates a form in that group. Use the menu to pick a different group if needed.</p><p>New forms created from a group source are pre-assigned to that group. You can change the group later in the form builder <strong>Settings</strong> tab.</p><h2 id="assigning-and-moving-forms" tabindex="-1">Assigning and Moving Forms <a class="header-anchor" href="#assigning-and-moving-forms" aria-label="Permalink to &quot;Assigning and Moving Forms&quot;">​</a></h2><p>Assign a group per form in the form builder <strong>Settings</strong> tab. The setting is hidden when no groups exist or when editing a stencil.</p><p>On the forms index, use the <strong>Move to group</strong> bulk action to move one or more forms into a group or back to <strong>Ungrouped</strong>.</p><h2 id="submissions-index" tabindex="-1">Submissions Index <a class="header-anchor" href="#submissions-index" aria-label="Permalink to &quot;Submissions Index&quot;">​</a></h2><p>When groups exist, the submissions index sidebar groups forms under their form group headings, with an <strong>Ungrouped</strong> section only when ungrouped forms are visible.</p><h2 id="form-templates" tabindex="-1">Form Templates <a class="header-anchor" href="#form-templates" aria-label="Permalink to &quot;Form Templates&quot;">​</a></h2><p>Form templates control front-end rendering. They are separate from form groups. Use form groups for control-panel organisation and templates for rendering.</p>',43)])])}const d=e(n,[["render",a]]);export{h as __pageData,d as default};
